def transpose(m):
    if not m:
        return []

    # Find the maximum row length
    max_len = max(len(row) for row in m)

    # Pad all rows to the same length with None (or could use a different default)
    padded_m = [row + [None] * (max_len - len(row)) for row in m]

    result = []
    for col_idx in range(max_len):
        new_col = []
        for row in padded_m:
            if col_idx < len(row):
                new_col.append(row[col_idx])
        result.append(new_col)

    return result


